SELECT
*
FROM
${tableName}
WHERE
id >= #{begin}
AND id < #{end}
AND api_code = #{apiCode}

SELECT
*
FROM
${tableName}
WHERE
id > #{begin}
AND api_code = #{apiCode}
AND batch_number = #{batchNumber}
order by id asc limit 5000;

