select cus_batch as cusBatch, group_type as groupType
from b_marketing_sync_${apiCode}
where applet_date = #{beginTime}
group by cus_batch,group_type

select group_type as groupType
from b_marketing_sync_${apiCode}
where cus_batch = #{cusBatch} and applet_date = #{beginTime}
group by group_type

	select cus_batch
	from b_marketing_sync_info
	where api_code = #{api_code}
   and create_time>= #{beginTime} and create_time < #{endTime}
	group by cus_batch

select count(1)
from  b_marketing_sync_${apiCode}
where cus_batch = #{cusBatch}
and group_type = #{groupType}
and applet_date= #{appletDate}

select count(1)
from  b_marketing_user_${apiCode}
where batch_number = #{batchNumber}

select *
from b_marketing_sync_${apiCode}
where request_batch = #{requestId}

select *
from b_marketing_sync_${apiCode}
where status = 1

	and cust_num = #{custNum}


	and cell = #{cell}

order by applet_time desc limit 1

select t1.cust_num, t1.cell, t1.user_type, t1.create_time, t1.applet_time
from b_marketing_sync_${apiCode} as t1,
(select id
from b_marketing_sync_${apiCode}
where


		 create_time > #{beginTime} and create_time <= #{endTime}


		 create_time > #{beginTime}


order by create_time, id limit ${page*2000},2000) as t2
where t1.id = t2.id;

select * from b_marketing_sync_${apiCode}
where cust_num = #{custNum} and status = 1

	and user_type = #{userType}

order by create_time desc limit 1
